def run_tuners(file, budget, seed, maxlives):
    used_budget = 0
    lives = 0
    history = {}
    best = float('inf')
    cursor = 0
    while used_budget < budget and lives < maxlives:
        configuration = []
        index = seed + cursor * 3
        for values in file.independent_set:
            configuration.append(values[index % len(values)])
            index //= len(values)
        before = used_budget
        used_budget, lives, history, best, score, mapped = evaluate(
            used_budget, lives, history, best, configuration
        )
        cursor += 1
        if used_budget == before and cursor > budget * 100:
            break
    return best

